contracts.obligation:
let mut it = range_difference(&(0usize..0usize), &(0usize..10usize));
let r0 = it.next();
assert(r0.is_none());

let mut it = range_difference(&(0usize..0usize), &(0usize..0usize));
let r0 = it.next();
assert(r0.is_none());

let mut it = range_difference(&(0usize..10usize), &(0usize..10usize));
let r0 = it.next();
assert(r0.is_none());

let mut it = range_difference(&(0usize..10usize), &(0usize..0usize));
let r0 = it.next();
let r1 = it.next();
assert(r0 == Some(0usize..10usize) && r1.is_none());

let mut it = range_difference(&(0usize..10usize), &(3usize..7usize));
let r0 = it.next();
let r1 = it.next();
let r2 = it.next();
assert(r0 == Some(0usize..3usize) && r1 == Some(7usize..10usize) && r2.is_none());

let mut it = range_difference(&(5usize..10usize), &(0usize..6usize));
let r0 = it.next();
let r1 = it.next();
assert(r0 == Some(6usize..10usize) && r1.is_none());

let mut it = range_difference(&(0usize..10usize), &(0usize..5usize));
let r0 = it.next();
let r1 = it.next();
assert(r0 == Some(5usize..10usize) && r1.is_none());

let mut it = range_difference(&(5usize..10usize), &(6usize..12usize));
let r0 = it.next();
let r1 = it.next();
assert(r0 == Some(5usize..6usize) && r1.is_none());

let mut it = range_difference(&(0usize..10usize), &(5usize..10usize));
let r0 = it.next();
let r1 = it.next();
assert(r0 == Some(0usize..5usize) && r1.is_none());

let recv = AtomicCpuSet::new(CpuSet::new_empty());
recv.add(CpuId::try_from(0usize).unwrap(), Ordering::Relaxed);
let out = recv.contains(CpuId::try_from(0usize).unwrap(), Ordering::Relaxed);
assert(out);

